const Arg = struct { arg: u64, head: usize };

fn read_arg(b: []const u8, low: u8) CodecError!Arg {
    if (low < 24) return .{ .arg = low, .head = 1 };
    switch (low) {
        24 => {
            if (b.len < 2) return error.UnexpectedEof;
            return .{ .arg = b[1], .head = 2 };
