            21 => return .{ .value = .{ .boolean = true }, .consumed = n },
            22, 23 => return .{ .value = .{ .null = {} }, .consumed = n },
            25 => return .{ .value = .{ .float = half_to_f64(@intCast(arg)) }, .consumed = n },
